import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as n,a as r,b as s,c as i,d as l,e as h,f as c,g as p,h as d,i as u,j as m,k as g}from"./chunks/M-S-SW-BJe4.xYg88VDv.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as y}from"./chunks/EN.P9aPnFBv.js";import{_ as b,o as f,c as w,a3 as x}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"BlueJay Watch","description":"","frontmatter":{},"headers":[],"relativePath":"smartwatch/bluejay.md","filePath":"smartwatch/bluejay.md"}'),v={name:"smartwatch/bluejay.md"};function _(S,o,B,k,D,T){return f(),w("div",null,[...o[0]||(o[0]=[x('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Smart Watch Features<br>   BlueJay Watch</p></div><p>You can buy your BlueJay Watch <a href="https://bluejay.website/" target="_blank" rel="noreferrer">here: <img src="'+n+'" style="zoom:100%;"></a></p><p>The <a href="https://bluejay.website/shop" target="_blank" rel="noreferrer">BlueJay U3</a> is the current watch and is available now. It runs the full xDrip package on Android and connects directly to your G6, G7 and Dexcom ONE/ONE+ sensors.</p><p>The earlier X2, GTS, U1 and U2 models are <strong>no longer sold</strong>. Their setup instructions are kept below for existing owners.<br> Legacy references: <a href="https://bluejay.website/shop/product/bluejay-gts-26" target="_blank" rel="noreferrer">GTS</a> (standalone or with xDrip), <a href="https://bluejay.website/shop/product/bluejay-u1-27" target="_blank" rel="noreferrer">U1</a> and <a href="https://bluejay.website/shop/product/bluejay-u2-28" target="_blank" rel="noreferrer">U2</a>.</p><div class="info custom-block"><p class="custom-block-title">Sharing BG</p><p>BlueJay X2/GTS are only Bluetooth and cannot share BG data without being connected to your phone xDrip.<br> The U1/U2/U3 run full xDrip and can also relay readings to a phone or other followers over Bluetooth (xDrip Link) or the internet (xDrip Sync).</p></div><p>BlueJay watches are powerful companions for your G6, G7 and 1/1+ sensors. They connect directly to the transmitter but you need to be aware of the limitations.</p><h5 id="g6g7-and-11" tabindex="-1">G6/G7 and 1/1+ <a class="header-anchor" href="#g6g7-and-11" aria-label="Permalink to &quot;G6/G7 and 1/1+&quot;">​</a></h5><p>These transmitters have two Bluetooth slots: phone and non-phone.<br> You can configure your slots as per the table below. Only two devices can be connected simultaneously to the transmitter, each one using a unique slot.<br> By default BlueJay uses the non-phone slot. See <a href="#run-collector">here for GTS</a> for how to change this setting.</p><p>U1, U2 and U3 need to be connected first to the sensor. Once connected, you can also enable the second connection and the watch will automatically select the available free slot.</p><table tabindex="0"><thead><tr><th>Vendor app</th><th>Receiver</th><th>Connected pump</th><th>BlueJay Watch</th></tr></thead><tbody><tr><td>Cannot be used</td><td>Cannot be used</td><td>Cannot be used</td><td>Non-phone slot <strong>xDrip uses phone slot</strong></td></tr><tr><td><strong>Uses phone slot</strong></td><td>Cannot be used</td><td>Cannot be used</td><td>Non-phone slot</td></tr><tr><td>Cannot be used</td><td><strong>Uses non-phone slot</strong></td><td>Cannot be used</td><td>Phone slot</td></tr><tr><td>Cannot be used</td><td>Cannot be used</td><td>t:slim, Omnipod 5 <strong>use non-phone slots</strong></td><td>Phone slot</td></tr><tr><td>Cannot be used</td><td>Cannot be used</td><td>CamAPS, DBLG1 <strong>use phone slot</strong></td><td>Non-phone slot</td></tr></tbody></table><p><em>Note: xDrip uses the phone slot by default, non-phone slot requires engineering mode</em></p><h2 id="bluejay-u3" tabindex="-1">BlueJay U3 <a class="header-anchor" href="#bluejay-u3" aria-label="Permalink to &quot;BlueJay U3&quot;">​</a></h2><p>The U3 runs full Android and the xDrip core on the watch itself. You set it up on the watch and can optionally relay readings to your phone.</p><h3 id="u3-controls" tabindex="-1">U3 controls <a class="header-anchor" href="#u3-controls" aria-label="Permalink to &quot;U3 controls&quot;">​</a></h3><p>The U3 has two physical buttons: a <strong>Left</strong> button (orange) and a <strong>Right</strong> button. On the U1/U2 the right control was a winder; on the U3 that position is the camera.</p><ul><li>Press either button to wake the screen.</li><li>The <strong>Right</strong> button turns the screen off.</li><li>The <strong>Left</strong> button goes back.</li><li>Long-press the power button for the Shutdown / Reboot / SOS menu, then swipe the option you want to the right.</li></ul><h3 id="get-readings-on-the-u3" tabindex="-1">Get readings on the U3 <a class="header-anchor" href="#get-readings-on-the-u3" aria-label="Permalink to &quot;Get readings on the U3&quot;">​</a></h3><p>Set the sensor identifier on the watch in xDrip, exactly as you would on a phone: go to Settings  ›  Hardware Data Source  ›  DexcomG5/G6/G7.</p><ul><li><strong>G6</strong> — enter the <strong>Transmitter ID (TXID)</strong>.</li><li><strong>G7 / Dexcom ONE+</strong> — enter the <strong>4-digit pairing code</strong>.</li></ul><p>With a new sensor, set the ID/code on the watch first and let it get readings before setting it on any phone app. With a sensor that is already running with a phone app connected, temporarily disable the phone app (turn it off, disable Bluetooth, or move out of range), connect the watch, then re-enable the phone app once the watch has readings.</p><h3 id="transmitter-slot" tabindex="-1">Transmitter slot <a class="header-anchor" href="#transmitter-slot" aria-label="Permalink to &quot;Transmitter slot&quot;">​</a></h3><p>By default the U3 uses the <strong>non-phone slot</strong>. Refer to the <a href="#g6g7-and-11">slot table above</a> to choose the right slot. To move the watch to the <strong>phone slot</strong>, scan the corresponding QR code in:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Auto Configure</p></div><p>Avoid repeatedly swapping the device on a slot: the sensor can jam. The slot is a fixed configuration, not a hot-swap.</p><div class="warning custom-block"><p class="custom-block-title">G7 phone-channel update</p><p>If your watch stops getting <strong>G7</strong> readings, apply the watch software update: on the watch open <strong>Android Settings › Software Upgrade</strong>, connected to WiFi and on charge (battery &gt; 25%), check for updates and install.<br> Afterwards you can switch the watch to the phone channel by scanning the QR code shown in xDrip <strong>Settings › Auto-configure</strong>, then reboot the watch.<br> With this method the <strong>watch and a phone app cannot both</strong> get readings directly from the sensor: disable the phone app collector if the watch is the collector.</p></div><h3 id="snooze-an-xdrip-alarm" tabindex="-1">Snooze an xDrip alarm <a class="header-anchor" href="#snooze-an-xdrip-alarm" aria-label="Permalink to &quot;Snooze an xDrip alarm&quot;">​</a></h3><p>Long-press the <strong>orange Left button</strong> until the watch vibrates.</p><h3 id="relay-readings-to-your-phone-or-followers" tabindex="-1">Relay readings to your phone or followers <a class="header-anchor" href="#relay-readings-to-your-phone-or-followers" aria-label="Permalink to &quot;Relay readings to your phone or followers&quot;">​</a></h3><p>When the watch is the collector you can still feed your phone and other devices:</p><ul><li><strong>xDrip Link</strong> — watch ↔ phone over Bluetooth when in range. On the watch, open the <strong>xDrip Link</strong> app, enable it and scan its QR code in phone xDrip <strong>Settings › Auto Configure</strong>. BlueJay settings entered on the phone (including the TXID/pairing code) are copied to the watch. If the phone should not collect directly, set <a href="#run-phone-collector">Run Phone Collector</a> <strong>Off</strong> on the phone.</li><li><strong>xDrip Sync</strong> — relays readings over the internet (WiFi/4G) from a master to one or more followers, including watch-to-watch and phone-to-watch.</li></ul><div class="info custom-block"><p class="custom-block-title">Non-xDrip watch features</p><p>Inserting a SIM, WiFi, the camera, watch faces, straps, screen covers, Google account, phone calls, GPS, SOS calling, music and the on-watch software upgrade are documented by the vendor. See the BlueJay <a href="https://bluejay.website/faq" target="_blank" rel="noreferrer">Top Tips / FAQ</a>.</p></div><h2 id="legacy-models-x2-gts" tabindex="-1">Legacy models: X2 / GTS <a class="header-anchor" href="#legacy-models-x2-gts" aria-label="Permalink to &quot;Legacy models: X2 / GTS&quot;">​</a></h2><p>The following steps apply to the older X2 and GTS watches, which are no longer sold.</p><h3 id="pair-your-watch-to-xdrip-x2-and-gts" tabindex="-1">Pair your watch to xDrip (X2 and GTS) <a class="header-anchor" href="#pair-your-watch-to-xdrip-x2-and-gts" aria-label="Permalink to &quot;Pair your watch to xDrip (X2 and GTS)&quot;">​</a></h3><p>1 - Make sure the watch is charged before starting.</p><p>2 - Enable BlueJay and disable watch collector.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>3 - If you have a BlueJay GTS continue to 6.<br> If you have a BlueJay X2 it should show a QR code on the screen.<br><img src="'+r+'" style="zoom:40%;"><br> If you see it continue to 7.</p><p>4 - Launch BlueJay Panel and Scan.</p><div class="admonition xdripitem"><p class="admonition-title">Launch BlueJay Panel</p></div><img src="'+s+'" style="zoom:76%;"> When the watch is detected you should see its Mac address. Select it. <img src="'+i+'" style="zoom:66%;"><br> If xDrip doesn&#39;t find the watch, try to restart your phone and retry. If you still can&#39;t find it: you can enter the watch Mac address manually here <div class="admonition xdripitem"><p class="admonition-title">BlueJay Advanced Settings</p><p> BlueJay Mac</p></div><p>The QR code should now appear on the watch, if you see it: continue to 7.</p><p>5 - If the QR code didn&#39;t show up on your watch, select QR and retry.<br><img src="'+l+'" style="zoom:76%;"><br> If you still can&#39;t see the QR code try REBOOT then <a href="https://bluejay.website/contactus" target="_blank" rel="noreferrer">contact</a> the vendor for assistance or seek help <a href="https://gitter.im/jamorham/BlueJay" target="_blank" rel="noreferrer">here</a>.</p><p>6 - On the GTS follow this menu sequence to display the QR code:<br> Settings Menu -&gt; Admin Menu -&gt; Show QR Code<br><img src="'+h+'" style="zoom:76%;"></p><p>7 - In xDrip scan the watch QR code</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Auto Configure</p></div><p>You need to authorize xDrip to access the phone camera.<br> Scan the QR code displayed on the watch.<br><img src="'+c+'" style="zoom:50%;"></p><p>Set up the watch as a follower and you should see your BG within minutes.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Send Readings <span class="symbol"><img src="'+y+'" style="zoom:75%;"></span></p></div><p>Check <a href="./../troubleshoot/systemstatus.html">System Status</a> to confirm the watch paired correctly. Swipe to the advanced status tab BlueJay.</p><img src="'+p+'" style="zoom:66%;"><p>If the xDrip core is not installed you should install it now.</p><h3 id="install-the-xdrip-core" tabindex="-1">Install the xDrip Core <a class="header-anchor" href="#install-the-xdrip-core" aria-label="Permalink to &quot;Install the xDrip Core&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Put the watch on charge whilst installing the core</p></div><p>In xDrip System Status, BlueJay advanced status, tap the red line xDrip Core: Not Installed.</p><img src="'+d+'" style="zoom:71%;"><p>Select OK to update the watch.</p><img src="'+u+'" style="zoom:79%;"><p>Check System Status afterwards, you should see the core installed.</p><img src="'+m+'" style="zoom:66%;"><h3 id="run-collector" tabindex="-1">Run collector <a class="header-anchor" href="#run-collector" aria-label="Permalink to &quot;Run collector&quot;">​</a></h3><p>Run collector means you will be using the watch without necessarily having your phone with you.</p><p>You must set up the watch using xDrip if you use an X2 model.<br> For GTS you can do it directly through the watch <a href="https://bluejay.website/gts-menu-top" target="_blank" rel="noreferrer">menu</a>, without using xDrip.</p><p>In order to use the watch with xDrip you must have a transmitter directly connected to xDrip with BG data currently displaying in xDrip.</p><p>Define which slot will connect to the transmitter. Refer to the table <a href="#g6g7-and-11">above</a> to set up your slots.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Advanced Settings</p></div><h5 id="run-phone-collector" tabindex="-1">Run Phone Collector <a class="header-anchor" href="#run-phone-collector" aria-label="Permalink to &quot;Run Phone Collector&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Run Phone Collector <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Also run the standard collector on this phone. Only turn this off if you don&#39;t want this phone itself to be connecting to the transmitter.</p></div><p>Enable/disable the connection of xDrip to the transmitter (using the phone slot).</p><h5 id="bluejay-uses-phone-slot" tabindex="-1">BlueJay uses Phone Slot <a class="header-anchor" href="#bluejay-uses-phone-slot" aria-label="Permalink to &quot;BlueJay uses Phone Slot&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">BlueJay uses Phone Slot <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> This allows the BlueJay to occupy the phone slot on the transmitter. Select this if you want another non-phone device to be able to connect to the transmitter and you are not using a phone to connect to the transmitter.</p></div><p>By default BlueJay uses the non-phone slot. You can let it use the phone slot with this option but you should then disable Run Phone Collector above.</p><p>Once slots are set up you can enable the watch as a standalone collector device.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>You will then see your phone xDrip is not connected to the transmitter anymore: BlueJay is.<br> When your watch is within Bluetooth range, your phone should receive BG from BlueJay.</p><img src="'+g+'" style="zoom:66%;"><h2 id="bluejay-gts" tabindex="-1">BlueJay GTS <a class="header-anchor" href="#bluejay-gts" aria-label="Permalink to &quot;BlueJay GTS&quot;">​</a></h2><p>GTS doesn&#39;t need xDrip to be set up but the steps above should also apply if you want to do so.</p><p>See the video <a href="https://www.youtube.com/watch?v=JM5cw-xVAZk" target="_blank" rel="noreferrer">here</a> for a guided tour.</p><p>See here <a href="https://www.youtube.com/watch?v=6YpjuZe2c_Q" target="_blank" rel="noreferrer">how</a> to connect to the transmitter.</p><h2 id="bluejay-u1u2-legacy" tabindex="-1">BlueJay U1/U2 (legacy) <a class="header-anchor" href="#bluejay-u1u2-legacy" aria-label="Permalink to &quot;BlueJay U1/U2 (legacy)&quot;">​</a></h2><p>The U1 and U2 are no longer sold but run the same full-xDrip package as the U3, so the <a href="#bluejay-u3">U3 setup</a> above applies. See the vendor <a href="https://bluejay.website/faq" target="_blank" rel="noreferrer">Top Tips / FAQ</a> for U-series watch tips.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Last modified 18/7/2026</em></a></p>',93)])])}const j=b(v,[["render",_]]);export{C as __pageData,j as default};
